import React from "react";
import { Button } from "antd";

const MobileForm = ({ onBack }) => {
  return (
    <div className="mobile-form" style={{ padding: 16 }}>
      <h3>Formulario móvil</h3>
      <p>Versión móvil del formulario PWA.</p>
      <Button type="primary" onClick={onBack}>
        Volver
      </Button>
    </div>
  );
};

export default MobileForm;
